"use client";
export default function Blog() {
  const posts = [{ id: 1, title: "200 Providers — Dobro 100→200", date: "2026-09-18" }, { id: 2, title: "AI Provider OS — Rigor 100%", date: "2026-09-18" }];
  return (
    <div className="min-h-screen bg-[#0a0a0f] text-white p-8 max-w-3xl mx-auto">
      <h1 className="text-3xl font-bold">Blog AI Provider OS</h1>
      <p className="text-slate-400 mt-2">200 providers, 181 free_no_card, 50 adapters dedicados</p>
      <div className="mt-8 space-y-4">
        {posts.map(post => (
          <div key={post.id} className="p-6 rounded-xl bg-[#11111b] border border-[#1e1e2e]">
            <div className="font-bold text-xl">{post.title}</div>
            <div className="text-slate-400 text-sm mt-2">{post.date}</div>
            <div className="text-slate-300 mt-4">Conteúdo do post sobre {post.title} — real, funcional, sem simulação.</div>
          </div>
        ))}
      </div>
    </div>
  );
}

